  "Creating…": { fr: "Création…", ar: "جارٍ الإنشاء…" },
  /* ----------------------- public homepage (bug 1) ------------------------ */
  "A complete visa desk behind your agency": { fr: "Un desk visa complet derrière votre agence", ar: "مكتب تأشيرات متكامل خلف وكالتك" },
  "All destinations →": { fr: "Toutes les destinations →", ar: "كل الوجهات ←" },
  "Join the agencies and wholesalers running their entire visa desk on our platform.": { fr: "Rejoignez les agences et grossistes qui gèrent tout leur desk visa sur notre plateforme.", ar: "انضم إلى الوكالات وتجار الجملة الذين يديرون مكتب التأشيرات بالكامل على منصتنا." },
  "Processing volumes your agency can scale with": { fr: "Des volumes de traitement qui évoluent avec votre agence", ar: "أحجام معالجة تتوسع مع وكالتك" },
  "End-to-end application handling": { fr: "Gestion des dossiers de bout en bout", ar: "معالجة الطلبات من البداية إلى النهاية" },
  "From document checklist to embassy submission, every file is prepared, quality-checked and tracked by our operations team.": { fr: "De la checklist documentaire au dépôt à l'ambassade, chaque dossier est préparé, contrôlé et suivi par notre équipe d'opérations.", ar: "من قائمة مستندات التحقق إلى التقديم للسفارة، يُجهَّز كل ملف ويُفحص ويُتتبع من قبل فريق عملياتنا." },
  "Configuration-driven precision": { fr: "Précision pilotée par la configuration", ar: "دقة تقودها الإعدادات" },
  "Requirements, fees and processing times per destination are maintained centrally, so your agency always quotes the current rules.": { fr: "Exigences, frais et délais par destination sont maintenus centralement — votre agence annonce toujours les règles en vigueur.", ar: "تُدار المتطلبات والرسوم ومدد المعالجة لكل وجهة مركزيًا، فتعرض وكالتك دائمًا القواعد الحالية." },
  "Full visibility for your team": { fr: "Visibilité totale pour votre équipe", ar: "رؤية كاملة لفريقك" },
  "Your agency portal shows live status, document review results, wallet activity and direct communication with our case officers.": { fr: "Votre portail agence affiche statuts en direct, résultats des revues de documents, activité du portefeuille et communication directe avec nos gestionnaires.", ar: "يعرض بوابة وكالتك الحالة المباشرة ونتائج مراجعة المستندات ونشاط المحفظة والتواصل المباشر مع مسؤولي الملفات لدينا." },
  "Prepaid wallet billing": { fr: "Facturation par portefeuille prépayé", ar: "فوترة بمحفظة مدفوعة مسبقًا" },
  "No per-file invoices. Fund your agency wallet once and every submission is charged automatically with a complete audit trail.": { fr: "Pas de factures par dossier. Alimentez votre portefeuille une fois et chaque soumission est débitée automatiquement avec une piste d'audit complète.", ar: "لا فواتير لكل ملف. موّل محفظة وكالتك مرة واحدة ويُخصم كل طلب تلقائيًا مع سجل تدقيق كامل." },
  "Select visa": { fr: "Choisir le visa", ar: "اختر التأشيرة" },
  "Pick destination and visa category from the live catalogue.": { fr: "Choisissez destination et catégorie de visa dans le catalogue en direct.", ar: "اختر الوجهة وفئة التأشيرة من الكتالوج المباشر." },
  "Add applicants": { fr: "Ajouter les voyageurs", ar: "أضف المسافرين" },
  "Passenger details and passports are captured per traveller.": { fr: "Les détails des passagers et passeports sont saisis par voyageur.", ar: "تُسجل بيانات المسافرين وجوازاتهم لكل مسافر." },
  "The generated checklist tells your team exactly what to provide.": { fr: "La checklist générée indique exactement à votre équipe quoi fournir.", ar: "تخبر قائمة التحقق المولدة فريقك بما يجب تقديمه بالضبط." },
  "Submit & track": { fr: "Soumettre et suivre", ar: "أرسل وتتبع" },
  "Your wallet is charged, and the file moves through our workflow in real time.": { fr: "Votre portefeuille est débité et le dossier avance dans notre flux en temps réel.", ar: "تُخصم محفظتك ويتحرك الملف عبر سير عملنا في الوقت الفعلي." },
  "Europe": { fr: "Europe", ar: "أوروبا" },
  "Schengen and UK corridors with consolidated checklists.": { fr: "Couloirs Schengen et Royaume-Uni avec checklists consolidées.", ar: "ممرات شنغن والمملكة المتحدة بقوائم تحقق موحدة." },
  "Americas": { fr: "Amériques", ar: "الأمريكتان" },
  "US, Canada and regional visitor programmes.": { fr: "États-Unis, Canada et programmes visiteurs régionaux.", ar: "الولايات المتحدة وكندا وبرامج الزيارة الإقليمية." },
